// === Tab: mySketch ===
function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  angleMode(DEGREES);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function draw() {
  colorMode(HSB, 360, 100, 100, 1.0);

  // 深海をイメージした深い紺色
  background(220, 90, 15);

  // ライトの設定
  ambientLight(210, 80, 40); 
  directionalLight(190, 40, 80, 0.5, 0.7, -0.5);

  let animationTime = frameCount * 0.1;

  rotateX(55);
  noStroke();

  // グリッド数の調整（見た目の細かさと軽快な動作のバランスのため20に調整）
  let gridCount = 20;
  let shorterSide = max(width, height);
  let gridSize = (shorterSide / gridCount) * 1.0;

  // --- 【変更ポイント】画面の一番上（奥の水平線）から描画するための範囲設定 ---
  // 横幅を1.8倍、縦の奥行きを2.5倍に広げ、パースによって縮む奥の領域をカバーします
  let extWidth = width * 4;
  let extHeight = height * 5; 

  // 平行移動量を「-extHeight * 0.8」まで引き上げ、
  // 描画のスタート位置を画面の上端よりもさらに奥の方向へ移動させます
  translate(-extWidth / 2, -extHeight * 0.8, -100);

  for (let x = 0; x < extWidth; x += (Math.max(0.001, Math.abs(gridSize)) || 1)) {
    for (let y = 0; y < extHeight; y += (Math.max(0.001, Math.abs(gridSize)) || 1)) {
      let centerX = x + gridSize / 2;
      let centerY = y + gridSize / 2;

      let zOffsetRange = shorterSide * 0.25;

      // 波の動き
      let swell = noise(centerX * 0.002, centerY * 0.002, animationTime * 0.1);
      let ripple = noise(centerX * 0.015, centerY * 0.015, animationTime * 0.4);
      let combinedNoise = swell * 0.7 + ripple * 0.3;

      let zOffset = map(combinedNoise, 0, 1, -zOffsetRange, zOffsetRange);

      // 高さに応じた色変化
      let hue = map(zOffset, -zOffsetRange, zOffsetRange, 230, 190);
      let sat = map(zOffset, -zOffsetRange, zOffsetRange, 95, 60);
      let bri = map(zOffset, -zOffsetRange, zOffsetRange, 30, 85);
      let alpha = map(zOffset, -zOffsetRange, zOffsetRange, 0.6, 0.95);

      fill(hue, sat, bri, alpha);

      push();
      translate(x, y, zOffset);
      plane(gridSize * 1.15, gridSize * 1.15);
      pop();
    }
  }
}
